   <meta charset="UTF-8">
   <meta name="viewport" content="width=device-width, initial-scale=1.0">
   <title>Terms Consent Form</title>
   <style>
     :root {
       color-scheme: light;
       --bg: #f5f7fb;
       --card: #ffffff;
       --text: #172033;
       --muted: #667085;
       --border: #d9e0ea;
       --primary: #4f46e5;
       --primary-dark: #4338ca;
       --ring: rgba(79, 70, 229, 0.22);
       --shadow: 0 24px 70px rgba(23, 32, 51, 0.12);
     }

     * {
       box-sizing: border-box;
     }

     body {
       min-height: 100vh;
       margin: 0;
       display: grid;
       place-items: center;
       padding: 32px;
       background:
         radial-gradient(circle at top left, rgba(79, 70, 229, 0.14), transparent 32rem),
         linear-gradient(135deg, #f8fafc 0%, var(--bg) 100%);
       color: var(--text);
       font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
     }

     .app-shell {
       width: min(100%, 460px);
     }

     .consent-card {
       padding: 32px;
       border: 1px solid rgba(217, 224, 234, 0.8);
       border-radius: 28px;
       background: rgba(255, 255, 255, 0.9);
       box-shadow: var(--shadow);
       backdrop-filter: blur(14px);
     }

     .eyebrow {
       margin: 0 0 12px;
       color: var(--primary);
       font-size: 0.78rem;
       font-weight: 800;
       letter-spacing: 0.08em;
       text-transform: uppercase;
     }

     h1 {
       margin: 0;
       font-size: clamp(2rem, 6vw, 2.6rem);
       line-height: 1.05;
       letter-spacing: -0.045em;
     }

     .intro {
       margin: 14px 0 28px;
       color: var(--muted);
       font-size: 1rem;
       line-height: 1.6;
     }

     .form-field {
       display: grid;
       grid-template-columns: auto 1fr;
       gap: 12px;
       align-items: start;
       padding: 18px;
       border: 1px solid var(--border);
       border-radius: 18px;
       background: #fbfcff;
       transition: border-color 160ms ease, box-shadow 160ms ease, background 160ms ease;
     }

     .form-field:focus-within {
       border-color: var(--primary);
       box-shadow: 0 0 0 5px var(--ring);
       background: #ffffff;
     }

     input[type="checkbox"] {
       width: 22px;
       height: 22px;
       margin: 2px 0 0;
       accent-color: var(--primary);
       cursor: pointer;
     }

     label {
       display: block;
       color: var(--text);
       font-weight: 700;
       line-height: 1.4;
       cursor: pointer;
     }

     .helper-text {
       grid-column: 2;
       margin: -4px 0 0;
       color: var(--muted);
       font-size: 0.92rem;
       line-height: 1.5;
     }

     button {
       width: 100%;
       margin-top: 22px;
       border: 0;
       border-radius: 16px;
       padding: 15px 18px;
       background: var(--primary);
       color: #ffffff;
       font: inherit;
       font-weight: 800;
       cursor: pointer;
       box-shadow: 0 12px 24px rgba(79, 70, 229, 0.28);
       transition: transform 160ms ease, background 160ms ease, box-shadow 160ms ease;
     }

     button:hover {
       background: var(--primary-dark);
       box-shadow: 0 16px 30px rgba(79, 70, 229, 0.34);
       transform: translateY(-1px);
     }

     button:focus-visible {
       outline: 4px solid var(--ring);
       outline-offset: 3px;
     }

     @media (max-width: 520px) {
       body {
         padding: 20px;
       }

       .consent-card {
         padding: 24px;
         border-radius: 24px;
       }
     }
   </style>
 </head>
 <body>
   <main id="root" class="app-shell"></main>

   <script>
     const ConsentCheckbox = () => `
       <div class="form-field">
         <input id="terms" name="terms" type="checkbox" required aria-describedby="terms-helper">
         <label for="terms">I agree to the terms of use.</label>
         <p id="terms-helper" class="helper-text">Required to continue with your submission.</p>
       </div>
     `;

     const ConsentForm = () => `
       <section class="consent-card" aria-labelledby="form-title">
         <p class="eyebrow">Consent</p>
         <h1 id="form-title">Review and agree</h1>
         <p class="intro">Confirm your acceptance before submitting the form.</p>
         <form action="#" method="post">
           ${ConsentCheckbox()}
           <button type="submit">Submit agreement</button>
         </form>
       </section>
     `;

     const App = () => ConsentForm();

     document.getElementById("root").innerHTML = App();
   </script>
 </body>
 </html>

')
